protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF9 changed the default discriminator property from "Discriminator" to "$type".
        // Preserve "Discriminator" so existing 500K documents remain queryable and
        // direct SQL queries (c.Discriminator) continue to work.
        entity.HasDiscriminator<string>("Discriminator");

        // EF9 changed id format from "Product|123" to just "123".
        // Preserve the old compound format so existing documents are still accessible.
        entity.HasRootDiscriminatorInJsonId(true);
    });
    // Removed HasIndex — EF9 Cosmos provider now throws on HasIndex calls.
    // Manage indexing through the container's indexing policy in Azure Portal/Bicep.
}

